// ConfigToEnvVar converts Config to environment variable key-value pairs.
func ConfigToEnvVar(v *Config) map[string]string {
	if v == nil {
		return nil
	}
	result := make(map[string]string)
	result["PROTO_SERVICES_SAML_CONFIG_ENTITY_ID"] = v.EntityId
	result["PROTO_SERVICES_SAML_CONFIG_BASE_URL"] = v.BaseUrl
	result["PROTO_SERVICES_SAML_CONFIG_ASSERTION_LIFETIME_SECONDS"] = strconv.FormatInt(v.AssertionLifetimeSeconds, 10)
	result["PROTO_SERVICES_SAML_CONFIG_METADATA_CACHE_TTL_SECONDS"] = strconv.FormatInt(v.MetadataCacheTtlSeconds, 10)
	result["PROTO_SERVICES_SAML_CONFIG_TRACE_ID"] = v.TraceId
	result["PROTO_SERVICES_SAML_CONFIG_NOOP"] = strconv.FormatBool(v.Noop)
	return result
}

// ConfigFromEnvVar creates Config from environment variable key-value pairs.
